<script>
 import { terminalSession,terminalTab,terminalAvailability,terminalShell,terminalPresets } from './terminal-state.js';
 import { terminalFiles,terminalPrompt,TERMINAL_HELP } from './terminal-shell.js';
 import { terminalMenuItems } from './terminal-menus.js';
 import './terminal.css';
 let {state: terminalState,profile,windowId,files,available=true,active=true,execute,registerView}=$props();
 let root,scroller,output,input,error=$state(''),endpointId=$state(''),host=$state('studio.local'),user=$state('jake'),outcome=$state('connected'),banner=$state('Authored local endpoint. Files remain shared scene Files.'),endpointName=$state('');
 let session=$derived(terminalSession(terminalState,windowId)),tab=$derived(terminalTab(session)),capability=$derived(terminalAvailability(profile)),windows=$derived(profile.id.startsWith('windows11')),classic=$derived(/high-sierra|mojave/u.test(profile.id)),prompt=$derived(tab?terminalPrompt(tab,terminalFiles(files),profile):'');
 async function send(command,payload={}){const originalInput=input,originalTab=tab;if(command==='terminal.paste'&&input&&payload.start===undefined)payload={...payload,start:input.selectionStart,end:input.selectionEnd};if(command==='terminal.copy'&&document.activeElement===input&&input.selectionEnd>input.selectionStart)payload={...payload,source:'input',start:input.selectionStart,end:input.selectionEnd};const r=await execute?.(command,{windowId},payload);error=r?.status==='rejected'?r.error?.message??'Command unavailable.':'';if(r?.status==='applied'&&Number.isSafeInteger(r.caret)&&input===originalInput&&tab===originalTab&&input?.isConnected&&available){input.setSelectionRange(r.caret,r.caret);input.focus();}return r;}
 const tabSend=(command,payload={})=>send(command,{tabId:tab.id,...payload});
 async function run(){const originalTab=tab,originalInput=input,originalScroller=scroller,originalRoot=root;const r=await tabSend('terminal.run');if(r?.status!=='applied'||tab!==originalTab||input!==originalInput||scroller!==originalScroller||root!==originalRoot||!originalRoot?.isConnected||!available)return;originalInput?.focus();if(originalScroller)originalScroller.scrollTop=originalScroller.scrollHeight;}
 function keyboard(e){const command=e.metaKey||(windows&&e.ctrlKey&&e.shiftKey);if(command&&e.key.toLowerCase()==='t'){e.preventDefault();send('terminal.newTab');return;}if(command&&e.key.toLowerCase()==='w'){e.preventDefault();session.tabs.length>1?tabSend('terminal.closeTab'):send('terminal.closeWindow');return;}if(command&&e.key.toLowerCase()==='k'){e.preventDefault();tabSend('terminal.clear');return;}if(e.ctrlKey&&e.key.toLowerCase()==='c'){e.preventDefault();tab.selection.end>tab.selection.start||document.activeElement===input&&input.selectionEnd>input.selectionStart?tabSend('terminal.copy'):tabSend('terminal.interrupt');return;}if(command&&e.key.toLowerCase()==='c'){e.preventDefault();tabSend('terminal.copy');return;}if(command&&e.key.toLowerCase()==='v'||windows&&e.ctrlKey&&e.key.toLowerCase()==='v'){e.preventDefault();tabSend('terminal.paste');return;}if(e.target===input){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();run();}else if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();tabSend('terminal.history',{direction:e.key==='ArrowUp'?'previous':'next'});}}}
 function selection(){const s=window.getSelection();if(!output||!s?.rangeCount)return;const range=s.getRangeAt(0);if(!output.contains(range.startContainer)||!output.contains(range.endContainer))return;const pre=range.cloneRange();pre.selectNodeContents(output);pre.setEnd(range.startContainer,range.startOffset);const start=pre.toString().length;tabSend('terminal.selection',{start,end:start+range.toString().length});}
 function editEndpoint(e){endpointId=e.id;host=e.host;user=e.user;outcome=e.outcome;banner=e.banner;endpointName=e.id;}
 function saveEndpoint(){send('terminal.endpoint',{endpoint:{id:endpointId||endpointName,host,user,outcome,banner}});}
 $effect(()=>{if(!scroller||!tab||!available)return;scroller.scrollTop=tab.scrollTop;});
 $effect(()=>{if(!output||!tab||!available||!active)return;const {start,end}=tab.selection,s=window.getSelection();if(!s)return;if(start===end){if(s.rangeCount&&output.contains(s.getRangeAt(0).startContainer))s.removeAllRanges();return;}const walker=document.createTreeWalker(output,NodeFilter.SHOW_TEXT);let node,offset=0,from,to;while((node=walker.nextNode())){const limit=offset+node.textContent.length;if(!from&&start<=limit)from={node,offset:start-offset};if(end<=limit){to={node,offset:end-offset};break;}offset=limit;}if(!from||!to)return;const range=document.createRange();range.setStart(from.node,from.offset);range.setEnd(to.node,to.offset);s.removeAllRanges();s.addRange(range);});
 $effect(()=>{if(!root||!session||typeof registerView!=='function')return;const originalRoot=root,originalSession=session,originalState=terminalState,originalScroller=scroller,id=windowId;const mounted=()=>root===originalRoot&&originalRoot.isConnected&&terminalState===originalState&&terminalSession(terminalState,id)===originalSession&&available===true;const facade={available:mounted,getScrollTop:()=>mounted()&&scroller===originalScroller?Math.floor(originalScroller.scrollTop):null,focus(controlId,guard){if(guard?.()!==true||!mounted())return false;const control=Array.from(originalRoot.querySelectorAll('[data-control]')).find(c=>c.dataset.control===controlId);if(!control||control.disabled)return false;control.focus();return guard()===true&&mounted()&&document.activeElement===control;},scroll({top},guard){if(guard?.()!==true||!mounted()||scroller!==originalScroller||!originalScroller)return false;originalScroller.scrollTop=top;return guard()===true&&mounted();}};const unregister=registerView(id,facade);return ()=>unregister?.();});
</script>
{#if session&&tab}
<section bind:this={root} class="terminal-app" class:windows class:classic class:active aria-label={capability.label} onkeydown={keyboard} role="region">
 <nav class="terminal-local-menus" aria-label="Terminal menus">{#each terminalMenuItems(terminalState,windowId) as menu}<details><summary>{menu.label}</summary><div class="terminal-menu-popup">{#each menu.items as item}<button disabled={!item.enabled} onclick={()=>send(item.command,item.payload)}>{item.label}</button>{/each}</div></details>{/each}</nav>
 <div class="terminal-tabs" role="tablist" aria-label="Shell tabs"><div class="terminal-tab-strip">{#each session.tabs as t}<div class="terminal-tab" class:selected={t.id===session.activeTabId}><button role="tab" aria-selected={t.id===session.activeTabId} data-control={'tab-'+t.id} onclick={()=>send('terminal.activateTab',{tabId:t.id})}>{windows?'›_':''} {t.remote?.host??(windows?'Windows PowerShell':terminalShell(profile))}</button><button class="terminal-close-tab" aria-label="Close tab" disabled={session.tabs.length===1} onclick={()=>send('terminal.closeTab',{tabId:t.id})}>×</button></div>{/each}</div><button class="terminal-add-tab" data-control="new-tab" aria-label="New tab" disabled={session.tabs.length>=16} onclick={()=>send('terminal.newTab')}>+</button>{#if windows}<details class="terminal-profile-dropdown"><summary aria-label="New tab options">⌄</summary><div class="terminal-menu-popup">{#each terminalPresets(profile) as preset}<button onclick={()=>send('terminal.newTab',{profile:preset})}>New {preset.name} tab</button>{/each}<button onclick={()=>send('terminal.newWindow')}>New window</button><button onclick={()=>send('terminal.panel',{panel:'ssh'})}>Local SSH connection…</button><button onclick={()=>tabSend('terminal.copy')}>Copy selection</button><button onclick={()=>tabSend('terminal.paste')}>Paste</button><button onclick={()=>tabSend('terminal.clear')}>Clear scrollback</button><button onclick={()=>send('terminal.panel',{panel:'profiles'})}>Settings</button><button onclick={()=>send('terminal.panel',{panel:'help'})}>Help</button><button onclick={()=>send('terminal.closeWindow')}>Close window</button><button onclick={()=>send('terminal.quit')}>Exit Terminal</button></div></details>{/if}</div>
 <div class="terminal-screen" bind:this={scroller} onscroll={()=>{const top=Math.floor(scroller.scrollTop);if(top!==tab.scrollTop)send('terminal.scroll',{top});}} style:background={tab.appearance.background} style:color={tab.appearance.foreground} style:font-family={'"'+tab.appearance.font+'", monospace'} style:font-size={tab.appearance.fontSize+'px'} style:--terminal-cursor={tab.appearance.cursor}>
  <pre bind:this={output} class="terminal-output" onpointerup={selection} onkeyup={selection} oncopy={e=>{e.preventDefault();tabSend('terminal.copy');}}>{tab.lines.join('\n')}</pre>
  <form class="terminal-prompt" onsubmit={e=>{e.preventDefault();run();}}><label for={'terminal-input-'+windowId}>{prompt}</label><textarea id={'terminal-input-'+windowId} bind:this={input} data-control="input" rows="1" aria-label="Editable shell input" spellcheck="false" autocomplete="off" maxlength="4096" value={tab.input} oninput={e=>tabSend('terminal.input',{input:e.currentTarget.value})} oncopy={e=>{e.preventDefault();tabSend('terminal.copy');}} onpaste={e=>{e.preventDefault();tabSend('terminal.paste');}}></textarea><button class="terminal-run" aria-label="Run command" type="submit">↵</button></form>
 </div>
 <footer class="terminal-status"><span>{tab.remote?'Authored SSH: '+tab.remote.user+'@'+tab.remote.host:'Local '+terminalShell(profile)+'-style shell'} · {tab.appearance.name}</span><button onclick={()=>send('terminal.panel',{panel:'ssh'})}>Remote Connection…</button></footer>
 <div class="terminal-disclosure">{capability.disclosure}</div>
 {#if error}<div role="alert" class="terminal-error">{error}<button aria-label="Dismiss error" onclick={()=>error=''}>×</button></div>{/if}
 {#if session.panel!=='none'}<div class="terminal-sheet-shade"><section class="terminal-sheet" role="dialog" aria-modal="true" aria-label={'Terminal '+session.panel}>
 {#if session.panel==='profiles'}<h2>{classic?'Preferences':'Settings'} — Profiles</h2><div class="terminal-settings-layout"><aside>{#each terminalPresets(profile) as preset}<button class:selected={tab.appearance.name===preset.name} onclick={()=>tabSend('terminal.profile',{values:preset})}>{preset.name}</button>{/each}</aside><div class="terminal-settings-text"><h3>Text</h3><label>Profile name<input maxlength="64" value={tab.appearance.name} onchange={e=>tabSend('terminal.profile',{values:{...tab.appearance,name:e.currentTarget.value}})}/></label><label>Font<select value={tab.appearance.font} onchange={e=>tabSend('terminal.profile',{values:{...tab.appearance,font:e.currentTarget.value}})}>{#each ['Menlo','Monaco','Cascadia Mono','Consolas'] as font}<option value={font}>{font}</option>{/each}</select></label><label>Size<input type="number" min="10" max="32" value={tab.appearance.fontSize} onchange={e=>tabSend('terminal.profile',{values:{...tab.appearance,fontSize:Number(e.currentTarget.value)}})}/></label>{#each [['background','Background'],['foreground','Text'],['cursor','Cursor']] as [key,label]}<label>{label}<input type="color" value={tab.appearance[key]} oninput={e=>tabSend('terminal.profile',{values:{...tab.appearance,[key]:e.currentTarget.value}})}/></label>{/each}<p>Changes affect this tab. New tabs inherit the era’s default profile; choose a preset from the new-tab menu on Windows.</p></div></div>
 {:else if session.panel==='ssh'}<h2>New Remote Connection</h2><p>Editable authored local endpoints. No SSH transport, passwords or real server access.</p><div class="terminal-settings-layout"><aside>{#each terminalState.endpoints as e}<button class:selected={endpointId===e.id} onclick={()=>editEndpoint(e)}>{e.user}@{e.host}</button>{/each}<button onclick={()=>{endpointId='';endpointName='';host='';user='jake';outcome='connected';banner='Authored local endpoint.';}}>+ Add Endpoint</button></aside><div>{#if !endpointId}<label>Endpoint ID<input maxlength="128" bind:value={endpointName}/></label>{/if}<label>Host<input maxlength="128" bind:value={host}/></label><label>User<input maxlength="64" bind:value={user}/></label><label>Authored outcome<select bind:value={outcome}><option value="connected">Connected</option><option value="refused">Connection refused</option><option value="denied">Permission denied</option></select></label><label>Banner<textarea maxlength="2048" bind:value={banner}></textarea></label><div class="terminal-sheet-buttons"><button onclick={saveEndpoint}>Save Endpoint</button><button disabled={!endpointId} onclick={()=>send('terminal.removeEndpoint',{endpointId})}>Remove</button><button disabled={!endpointId} onclick={async()=>{const r=await tabSend('terminal.input',{input:'ssh '+user+'@'+host});if(r?.status==='applied'){const runResult=await tabSend('terminal.run');if(runResult?.status==='applied'&&runResult.succeeded)await send('terminal.panel',{panel:'none'});}}}>Connect</button></div></div></div>
 {:else}<h2>Terminal Help</h2>{#each TERMINAL_HELP as line}<p>{line}</p>{/each}<p>Enter runs one bounded command. Up/Down retrieves command history. Ctrl+C interrupts input or copies selected scrollback. Paste inserts shared scene clipboard text without executing it. Scrollback retains the latest 512 lines / 64 KiB. File mutation failures retain input and history unchanged.</p><p>{capability.disclosure}</p>{/if}
 <div class="terminal-sheet-buttons"><button data-control="done" onclick={()=>send('terminal.panel',{panel:'none'})}>Done</button></div></section></div>{/if}
</section>
{/if}
